import { Component, computed, effect, inject, signal, untracked } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { LIMIT_PATTERN, ROLES, TERMS_PATTERN, RoleGrant, SETTINGS_INVALID, SettingsApi, roleError, settingsError } from './settings-api';

// The sheet's settings (its clerk limit: a clerk settles only claims whose due is at or below it;
// its floor: a claim's live due is at least it; its terms: a claim is due by its date plus them) with the form that saves the ones changed in it, and the role each user name holds with the form that sets one.
@Component({
  selector: 'app-settings',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="settings-heading">
      <h2 id="settings-heading">Settings</h2>
      <p>Clerk limit in force <strong data-testid="setting-clerk-limit-current">{{ clerkLimit() ?? '' }}</strong></p>
      <p>Floor in force <strong data-testid="setting-floor-current">{{ session.floor() }}</strong></p>
      <p>Terms in force (days) <strong data-testid="setting-terms-current">{{ session.terms() }}</strong></p>
      <form [formGroup]="settingsForm" (ngSubmit)="saveSettings()" aria-label="Settings">
        <label for="setting-clerk-limit">Clerk limit (blank: no limit)</label>
        <input id="setting-clerk-limit" data-testid="setting-clerk-limit" formControlName="clerkLimit" inputmode="decimal" autocomplete="off" />
        <label for="setting-floor">Floor (blank: 1.00)</label>
        <input id="setting-floor" data-testid="setting-floor" formControlName="floor" inputmode="decimal" autocomplete="off" />
        <label for="setting-terms">Terms in days (blank: 14)</label>
        <input id="setting-terms" data-testid="setting-terms" formControlName="terms" inputmode="numeric" autocomplete="off" />
        <button type="submit" data-testid="settings-save">Save settings</button>
        @if (settingsErr(); as err) {
          <p role="alert" data-testid="settings-error">{{ err }}</p>
        }
      </form>
      <form [formGroup]="roleForm" (ngSubmit)="saveRole()" aria-label="Set role">
        <label for="role-form-user">User</label>
        <input id="role-form-user" data-testid="role-form-user" formControlName="user" autocomplete="off" />
        <label for="role-form-role">Role ({{ roleNames }})</label>
        <input id="role-form-role" data-testid="role-form-role" formControlName="role" list="role-options" autocomplete="off" />
        <datalist id="role-options">
          @for (r of roles; track r) {
            <option [value]="r"></option>
          }
        </datalist>
        <button type="submit" data-testid="role-form-submit">Set role</button>
        @if (roleErr(); as err) {
          <p role="alert" data-testid="role-form-error">{{ err }}</p>
        }
      </form>
      <table data-testid="roles-list">
        <caption>Roles (anyone else is a clerk)</caption>
        <thead>
          <tr><th scope="col">User</th><th scope="col">Role</th></tr>
        </thead>
        <tbody>
          @for (g of sortedGrants(); track g.user) {
            <tr [attr.data-testid]="'role-row-' + g.user">
              <th scope="row" data-testid="role-user">{{ g.user }}</th>
              <td data-testid="role-value">{{ g.role }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Settings {
  protected readonly session = inject(Session);
  private readonly api = inject(SettingsApi);

  protected readonly roles = ROLES;
  protected readonly roleNames = ROLES.join(' or ');
  /** The sheet's clerk limit in force (two decimals); null when there is none. */
  protected readonly clerkLimit = signal<string | null>(null);
  /** The roles set on the sheet. */
  protected readonly grants = signal<RoleGrant[]>([]);
  protected readonly sortedGrants = computed(() => [...this.grants()].sort((a, b) => a.user.localeCompare(b.user)));
  protected readonly settingsErr = signal<string | null>(null);
  protected readonly roleErr = signal<string | null>(null);
  /** Whether a submit is waiting for its answer; a second submit meanwhile is ignored. */
  private savingSettings = false;
  private savingRole = false;
  /** Guards against a slower, older read landing over a newer one. */
  private readSeq = 0;

  protected readonly settingsForm = new FormGroup({
    clerkLimit: new FormControl('', { nonNullable: true }),
    floor: new FormControl('', { nonNullable: true }),
    terms: new FormControl('', { nonNullable: true }),
  });
  protected readonly roleForm = new FormGroup({
    user: new FormControl('', { nonNullable: true }),
    role: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.settingsForm.valueChanges.subscribe(() => this.settingsErr.set(null));
    this.roleForm.valueChanges.subscribe(() => this.roleErr.set(null));
    effect(() => {
      const id = this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.clerkLimit.set(null);
        this.grants.set([]);
        this.settingsErr.set(null);
        this.roleErr.set(null);
        this.settingsForm.reset({ clerkLimit: '', floor: '', terms: '' }, { emitEvent: false });
        this.roleForm.reset({ user: '', role: '' }, { emitEvent: false });
        if (id) void this.read(id);
      });
    });
  }

  protected async saveSettings(): Promise<void> {
    if (this.savingSettings) return;
    this.settingsErr.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const { clerkLimit, floor, terms } = this.settingsForm.controls;
    // only the settings typed into since the last save are saved (the clerk limit when none is)
    const saveFloor = floor.dirty;
    const saveTerms = terms.dirty;
    const saveLimit = clerkLimit.dirty || !(saveFloor || saveTerms);
    const limitValue = clerkLimit.value.trim();
    const floorValue = floor.value.trim();
    const termsValue = terms.value.trim();
    if ((saveLimit && limitValue !== '' && !LIMIT_PATTERN.test(limitValue))
        || (saveFloor && floorValue !== '' && !LIMIT_PATTERN.test(floorValue))
        || (saveTerms && termsValue !== '' && !TERMS_PATTERN.test(termsValue))) {
      this.settingsErr.set(SETTINGS_INVALID);
      return;
    }
    this.savingSettings = true;
    try {
      if (saveLimit) {
        const saved = await this.api.setClerkLimit(sheetId, limitValue);
        clerkLimit.markAsPristine();
        if (this.session.sheetId() === sheetId) this.clerkLimit.set(saved.clerkLimit);
      }
      if (saveFloor) {
        const saved = await this.api.setFloor(sheetId, floorValue);
        floor.markAsPristine();
        if (this.session.sheetId() === sheetId) this.session.floor.set(saved.floor);
      }
      if (saveTerms) {
        const saved = await this.api.setTerms(sheetId, termsValue);
        terms.markAsPristine();
        if (this.session.sheetId() === sheetId) this.session.terms.set(saved.terms);
      }
    } catch (e) {
      this.settingsErr.set(settingsError(e));
    } finally {
      this.savingSettings = false;
    }
  }

  protected async saveRole(): Promise<void> {
    if (this.savingRole) return;
    this.roleErr.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const user = this.roleForm.controls.user.value.trim();
    const role = this.roleForm.controls.role.value.trim();
    if (!/^\S+$/.test(user)) {
      this.roleErr.set('Enter a user name without spaces.');
      return;
    }
    if (!(ROLES as readonly string[]).includes(role)) {
      this.roleErr.set(`Choose a role: ${this.roleNames}.`);
      return;
    }
    this.savingRole = true;
    try {
      const grant = await this.api.setRole(sheetId, user, role);
      if (this.session.sheetId() === sheetId) {
        this.grants.update((gs) => [...gs.filter((g) => g.user !== grant.user), grant]);
      }
      this.roleForm.reset({ user: '', role: '' }, { emitEvent: false });
    } catch (e) {
      this.roleErr.set(roleError(e));
    } finally {
      this.savingRole = false;
    }
  }

  private async read(sheetId: string): Promise<void> {
    const seq = ++this.readSeq;
    try {
      const [settings, grants] = await Promise.all([this.api.get(sheetId), this.api.roles(sheetId)]);
      if (seq === this.readSeq) {
        this.clerkLimit.set(settings.clerkLimit);
        this.session.floor.set(settings.floor);
        this.session.terms.set(settings.terms);
        this.grants.set(grants);
      }
    } catch {
      if (seq === this.readSeq) this.settingsErr.set('Something went wrong loading settings; try again.');
    }
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

/** The roles a user name can hold on a sheet; a name without one is a clerk. */
export const ROLES = ['clerk', 'steward'] as const;

/** A limit of 0.00 or more with up to two decimals. */
export const LIMIT_PATTERN = /^\d{1,13}(\.\d{1,2})?$/;

/** Terms of a whole number of days. */
export const TERMS_PATTERN = /^\d{1,4}$/;

export interface Settings {
  /** Two decimals, as the server formats it; null when there is no limit. */
  clerkLimit: string | null;
  /** Two decimals, as the server formats it: a claim's live due is at least it. */
  floor: string;
  /** Days: a claim is due by its date plus them. */
  terms: number;
}

export interface RoleGrant {
  user: string;
  role: string;
}

// The sheet's settings and the roles user names hold on it, read and written through the server.
@Injectable({ providedIn: 'root' })
export class SettingsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  get(sheetId: string): Promise<Settings> {
    return firstValueFrom(this.http.get<Settings>(`${this.url(sheetId)}/settings`, { headers: this.headers() }));
  }

  setClerkLimit(sheetId: string, value: string): Promise<Settings> {
    return firstValueFrom(
      this.http.put<Settings>(`${this.url(sheetId)}/settings/clerk-limit`, { value }, { headers: this.headers() }),
    );
  }

  setFloor(sheetId: string, value: string): Promise<Settings> {
    return firstValueFrom(
      this.http.put<Settings>(`${this.url(sheetId)}/settings/floor`, { value }, { headers: this.headers() }),
    );
  }

  setTerms(sheetId: string, value: string): Promise<Settings> {
    return firstValueFrom(
      this.http.put<Settings>(`${this.url(sheetId)}/settings/terms`, { value }, { headers: this.headers() }),
    );
  }

  roles(sheetId: string): Promise<RoleGrant[]> {
    return firstValueFrom(this.http.get<RoleGrant[]>(`${this.url(sheetId)}/roles`, { headers: this.headers() }));
  }

  setRole(sheetId: string, user: string, role: string): Promise<RoleGrant> {
    return firstValueFrom(this.http.put<RoleGrant>(`${this.url(sheetId)}/roles`, { user, role }, { headers: this.headers() }));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export const SETTINGS_INVALID =
  'Enter a clerk limit of 0.00 or more with up to two decimals (blank: no limit) and a floor of 0.00 or more with up to two decimals (blank: 1.00) and terms of a whole number of days (blank: 14).';

export function settingsError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return SETTINGS_INVALID;
  return 'Something went wrong; try again.';
}

export function roleError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a user name without spaces and a role of clerk or steward.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The role was changed at the same moment; try again.';
  return 'Something went wrong; try again.';
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

// Who is signed in and which sheet is active. Everything else in the app is kept per sheet.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  /** The active sheet's today (yyyy-mm-dd): every date decision and default date uses it. */
  readonly today = signal<string | null>(null);
  /** The active sheet's floor (two decimals): a claim's live due is at least it. */
  readonly floor = signal('1.00');
  /** The active sheet's terms in days: a claim is due by its date plus them. */
  readonly terms = signal(14);
  /** Whether the people list shows retired people too: off at first, and kept as it is when a
   *  sheet is loaded. */
  readonly showRetired = signal(false);
  /** Bumped on every sheet load, so a load of the same id again re-reads what the sheet holds. */
  readonly loads = signal(0);

  /** Sign in by name; resolves to an error message, or null on success. */
  async signIn(name: string): Promise<string | null> {
    try {
      const res = await firstValueFrom(this.http.post<{ name: string }>('/api/session', { name }));
      this.user.set(res.name);
      return null;
    } catch (e) {
      return message(e, 'Enter a name to sign in.');
    }
  }

  /** Load a sheet by id (a new id starts an empty sheet); resolves to an error message, or null. */
  async loadSheet(id: string): Promise<string | null> {
    const user = this.user();
    if (!user) return 'Sign in first.';
    try {
      const res = await firstValueFrom(
        this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
          headers: { 'X-User': user },
        }),
      );
      this.sheetId.set(res.id);
      this.today.set(res.today);
      this.floor.set(res.floor);
      this.terms.set(res.terms);
      this.loads.update((n) => n + 1);
      return null;
    } catch (e) {
      return message(e, 'Enter a sheet id without spaces.');
    }
  }

  /** Change the active sheet's today; resolves to an error message, or null. */
  async setToday(today: string): Promise<string | null> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) return 'Load a sheet first.';
    try {
      const res = await firstValueFrom(
        this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
          headers: { 'X-User': user },
        }),
      );
      if (this.sheetId() === res.id) this.today.set(res.today);
      return null;
    } catch (e) {
      return message(e, 'Enter a date as yyyy-mm-dd.');
    }
  }
}

interface SheetView {
  id: string;
  today: string;
  floor: string;
  terms: number;
}

function message(e: unknown, invalid: string): string {
  return e instanceof HttpErrorResponse && e.status === 400 ? invalid : 'Something went wrong; try again.';
}
package net.officefloor.hq.app.sheet;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import net.officefloor.hq.app.session.CurrentUser;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets")
@Validated
public class SheetController {

    /** A sheet as the screen takes it: its id, its today, its floor with two decimals, and its
     *  terms in days. */
    public record SheetView(String id, LocalDate today, String floor, int terms) {
        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday(), sheet.getFloor().toPlainString(), sheet.getTerms());
        }
    }

    public record TodayChange(@NotNull LocalDate today) {
    }

    private final SheetService service;

    public SheetController(SheetService service) {
        this.service = service;
    }

    @PostMapping("/{id}/load")
    public SheetView load(
